#!/usr/bin/env python3
"""Отсутствие находок не означает отсутствия секрета.

Сценарии внешней проверки, переписанные здесь регрессионными тестами
ПРАВИЛЬНОГО поведения. Оба пути кончались одним: незакрытое значение уезжало
в копию настроек, то есть одна копия секрета превращалась в две.

  · JSON с BOM. Сборщик фактов читал `utf-8` и на таком файле возвращал
    None — список секретов выходил ПУСТЫМ. Копирование читало `utf-8-sig`,
    BOM ему не мешал: копия создавалась успешно, а вырезать в ней было
    «нечего», потому что находок «нет». Два чтения одного файла — два разных
    мнения о его содержимом, и решение принималось по более слепому.
  · Неразбираемый JSON. Копирование делало `shutil.copy2` — файл уезжал
    СЫРЫМ, вместе с тем, что в нём лежало. Комментарий у этой ветки гласил
    «вырезать нечего и незачем», то есть выводил утверждение о содержимом из
    неудачи разбора. Неудача разбора не сообщает о содержимом ничего.

Отсюда четыре проверяемых утверждения:

  1. сборщик фактов и копирование читают файл ОДНИМ чтением;
  2. копия очищается по свежему обходу того, что ляжет в копию, а не по
     списку находок, собранному раньше;
  3. перед сохранением проверяется сам ТЕКСТ копии — обход по структуре не
     заглядывает в имена полей;
  4. неразобранное получает отдельное состояние «не проверено»: копия не
     снимается вовсе, не меняется ничего, и человеку сказано, что именно
     осталось непроверенным.

Фикстуры нарочно без строк, похожих на настоящий ключ: берётся ФОРМА, которую
ловит сканер (имя поля указывает на секрет, значение плотное), а на месте
значения стоит слово, в котором нет ни одной латинской буквы. Значение
найденного секрета наружу не выходит — ни в копию, ни в сообщение об отказе,
и это здесь тоже проверяется.

Тест самодостаточен: только стандартная библиотека и сами инструменты.

  python3 -m pytest tests/external/test_backup_redaction.py -q
"""
from __future__ import annotations

import contextlib
import importlib.util
import io
import json
import tempfile
import unittest
from pathlib import Path

РЕПО = Path(__file__).resolve().parents[2]


def _загрузить(имя: str, путь: Path):
    спек = importlib.util.spec_from_file_location(имя, путь)
    мод = importlib.util.module_from_spec(спек)
    спек.loader.exec_module(мод)
    return мод


ap = _загрузить("ss_apply_cut",
                РЕПО / "plugins" / "superstack" / "tools" / "apply.py")
сборщик = _загрузить("ss_collect_cut",
                     РЕПО / "plugins" / "superstack" / "tools" / "probe" / "collect.py")

#: Значение на месте секрета. Настоящего ключа здесь нет и быть не должно:
#: латиницы в нём нет вовсе, спутать его с ключом невозможно. При этом сканер
#: ловит его по той же улике, что и живой токен, — имя поля указывает на
#: секрет, а значение плотное и не похоже на путь, ссылку или имя провайдера.
ВЫДУМАННЫЙ_СЕКРЕТ = "ВЫДУМАННЫЙ-ТОКЕН-ДЛЯ-ТЕСТА-7"

#: Поле, в котором он лежит. Имя — обычное для настроек Claude Code.
ПОЛЕ_СЕКРЕТА = "API_TOKEN"

#: Секрет, оказавшийся в ИМЕНИ поля, а не в значении. Обход по структуре имена
#: не читает — такой секрет виден только в тексте копии. Значение снова
#: выдумано: «придуманный7» ключом не является ни в каком виде.
ИМЯ_ПОЛЯ_С_СЕКРЕТОМ = "PASSWORD=придуманный7"

#: Находка, ради которой плагин вообще трогает настройки. Действие у неё
#: описанное и безобидное; проверяется копия, а не решатель.
НАХОДКА = {"id": "ctx.default-mode-unset", "class": "AUTO", "verdict": "FIX",
           "headline": "режим прав не задан"}


class Дом(unittest.TestCase):
    """Подставной дом: настоящий ~/.claude не участвует ни одной строкой."""

    def setUp(self):
        врем = tempfile.TemporaryDirectory()
        self.addCleanup(врем.cleanup)
        self.дом = Path(врем.name)
        self.настройки = self.дом / ".claude"
        self.настройки.mkdir(parents=True)
        прежние = (ap.HOME, ap.CLAUDE, ap.STATE, ap.BACKUPS, ap.QUARANTINE)

        def вернуть():
            (ap.HOME, ap.CLAUDE, ap.STATE, ap.BACKUPS, ap.QUARANTINE) = прежние

        self.addCleanup(вернуть)
        ap.HOME = self.дом
        ap.CLAUDE = self.настройки
        ap.STATE = self.настройки / "superstack"
        ap.BACKUPS = ap.STATE / "backups"
        ap.QUARANTINE = ap.STATE / "quarantine"

    # ---- вспомогательное ---------------------------------------------------
    @property
    def файл(self) -> Path:
        return self.настройки / "settings.json"

    def записать(self, данные: dict, *, bom: bool = False) -> None:
        self.файл.write_text(json.dumps(данные, ensure_ascii=False),
                             encoding="utf-8-sig" if bom else "utf-8")

    def прочитать(self) -> dict:
        return json.loads(self.файл.read_text(encoding="utf-8-sig"))

    def сломать(self, имя: str = "settings.local.json") -> Path:
        """Файл настроек, который не разбирается, и с секретом внутри.

        Висячая запятая и незакрытая скобка — то, чем ломается живой конфиг,
        когда его правят руками. Секрет лежит внутри нарочно: сырая копия
        унесла бы его целиком, и именно этого быть не должно.
        """
        путь = self.настройки / имя
        путь.write_text(
            '{\n  "env": {\n    "' + ПОЛЕ_СЕКРЕТА + '": "'
            + ВЫДУМАННЫЙ_СЕКРЕТ + '",\n  }\n', encoding="utf-8")
        return путь

    def находки(self, список: list = None) -> str:
        путь = self.дом / f"находки-{len(list(self.дом.glob('находки-*')))}.json"
        путь.write_text(json.dumps({"findings": список or [НАХОДКА]},
                                   ensure_ascii=False), encoding="utf-8")
        return str(путь)

    def копия(self, сведения: dict, имя: str = "settings.json") -> str:
        return (Path(сведения["dir"]) / имя).read_text(encoding="utf-8")

    def всё_состояние(self) -> str:
        """Всё, что инструмент записал под ~/.claude/superstack, одной строкой.

        Проверка «секрет никуда не уехал» обязана смотреть на ВЕСЬ след, а не
        на один ожидаемый файл: копия, журнал и любой соседний артефакт —
        одинаково открытые места.
        """
        куски = []
        if ap.STATE.is_dir():
            for f in sorted(ap.STATE.rglob("*")):
                if f.is_file():
                    куски.append(f.read_text(encoding="utf-8", errors="replace"))
        return "\n".join(куски)

    def отказ(self, вызов) -> str:
        with self.assertRaises(SystemExit) as поймано:
            вызов()
        return str(поймано.exception)

    def прогон(self, список: list = None) -> tuple:
        вывод, ошибки = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(вывод), contextlib.redirect_stderr(ошибки):
            код = ap.cmd_run([self.находки(список)])
        return код, вывод.getvalue(), ошибки.getvalue()

    def план(self, список: list = None) -> str:
        вывод = io.StringIO()
        with contextlib.redirect_stdout(вывод):
            ap.cmd_plan([self.находки(список)])
        return вывод.getvalue()


# ==========================================================================
# Одно декодирование на всех
# ==========================================================================
class ОдноЧтениеНаВсех(Дом):
    """Сборщик фактов и копирование обязаны видеть один и тот же файл."""

    def test_сборщик_фактов_разбирает_json_с_bom(self):
        """Пустой список секретов был следствием чтения, а не содержимого."""
        данные = {"env": {ПОЛЕ_СЕКРЕТА: ВЫДУМАННЫЙ_СЕКРЕТ}}
        self.записать(данные, bom=True)
        self.assertEqual(сборщик.read_json(self.файл), данные,
                         "сборщик фактов не разобрал файл с BOM — "
                         "список секретов по нему выйдет пустым")

    def test_обе_стороны_видят_одно_и_то_же(self):
        """Копия обязана содержать ровно то, что прочитал сборщик фактов."""
        данные = {"theme": "dark", "permissions": {"allow": ["Bash(ls)"]}}
        self.записать(данные, bom=True)
        сведения = ap.make_backup([])
        self.assertEqual(сборщик.read_json(self.файл), данные)
        self.assertEqual(json.loads(self.копия(сведения)), данные,
                         "копия и сборщик фактов разошлись в содержимом")


# ==========================================================================
# (а) JSON с BOM — секрет не уезжает в копию невырезанным
# ==========================================================================
class СекретИзФайлаСBOM(Дом):
    """Находок «нет» — это про сканер, а не про файл."""

    def setUp(self):
        super().setUp()
        self.записать({"theme": "dark",
                       "env": {ПОЛЕ_СЕКРЕТА: ВЫДУМАННЫЙ_СЕКРЕТ}}, bom=True)

    def test_секрет_вырезан_даже_при_пустом_списке_находок(self):
        """Ровно тот вход, на котором ломалось: находок ноль, секрет есть."""
        сведения = ap.make_backup([])
        текст = self.копия(сведения)
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, текст, "секрет уехал в копию")
        self.assertIn(ap.REDACTION_MARK, текст, "на месте секрета нет метки")

    def test_копия_остаётся_разбираемой(self):
        """Вырезание не имеет права испортить сам файл копии."""
        сведения = ap.make_backup([])
        копия = json.loads(self.копия(сведения))
        self.assertEqual(копия["theme"], "dark", "соседнее значение потеряно")
        self.assertIn(ap.REDACTION_MARK, копия["env"][ПОЛЕ_СЕКРЕТА])

    def test_в_полном_прогоне_секрет_тоже_не_уезжает(self):
        """Тот же путь целиком: находки без мест, применение, копия."""
        код, _, _ = self.прогон()
        self.assertEqual(код, 0)
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, self.всё_состояние(),
                         "секрет нашёлся в том, что инструмент записал")

    def test_живое_значение_на_месте(self):
        """Копия чистится, а настройки человека — нет: там секрет его."""
        ap.make_backup([])
        self.assertEqual(self.прочитать()["env"][ПОЛЕ_СЕКРЕТА],
                         ВЫДУМАННЫЙ_СЕКРЕТ,
                         "инструмент вырезал секрет из живого файла")


# ==========================================================================
# (б) неразбираемый JSON — сырого копирования нет, человеку сказано
# ==========================================================================
class НеразобранноеНеКопируется(Дом):
    """«Не разобрался» — отдельное состояние, а не разрешение копировать."""

    def setUp(self):
        super().setUp()
        self.записать({"theme": "dark"})
        self.сломанный = self.сломать()

    def test_копия_не_снимается(self):
        self.отказ(lambda: ap.make_backup([]))
        self.assertFalse(ap.BACKUPS.exists(),
                         "остался каталог копии — отказ должен быть до него")

    def test_сырого_копирования_не_происходит(self):
        self.отказ(lambda: ap.make_backup([]))
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, self.всё_состояние(),
                         "содержимое неразобранного файла уехало в копию")

    def test_человеку_названо_что_именно_не_проверено(self):
        сказано = self.отказ(lambda: ap.make_backup([]))
        self.assertIn(self.сломанный.name, сказано, "файл не назван")
        self.assertIn("не провер", сказано.lower(),
                      "не сказано, что содержимое осталось непроверенным")
        self.assertIn("не менял", сказано.lower(),
                      "не сказано, что ничего не изменено")

    def test_отказ_не_печатает_содержимое(self):
        сказано = self.отказ(lambda: ap.make_backup([]))
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, сказано,
                         "отказ сам вынес значение наружу")

    def test_прогон_ничего_не_меняет(self):
        self.отказ(lambda: self.прогон())
        self.assertEqual(self.прочитать(), {"theme": "dark"},
                         "настройки изменены без копии")

    def test_план_называет_непроверенное_заранее(self):
        """Человек узнаёт об этом ДО действия, а не в момент отказа."""
        сказано = self.план()
        self.assertIn(self.сломанный.name, сказано, "план молчит о файле")
        self.assertIn("не провер", сказано.lower(),
                      "план не говорит, что содержимое не проверено")

    def test_целый_файл_не_наказан_за_соседа(self):
        """Отказ обязан быть по делу: без сломанного соседа копия снимается."""
        self.сломанный.unlink()
        сведения = ap.make_backup([])
        self.assertIn("settings.json", сведения["files"])

    def test_файл_не_сложившийся_в_текст_это_тот_же_случай(self):
        """Настройки в UTF-16 — обычное дело для редакторов Windows.

        Байты, которые не складываются в текст, до разбора JSON не доходят
        вовсе. Без отдельной ветки инструмент падал бы здесь трейсбеком —
        то есть «не проверено» осталось бы несказанным, а человек не узнал бы
        ни причины, ни того, что копии нет.
        """
        self.сломанный.write_bytes(
            json.dumps({"env": {ПОЛЕ_СЕКРЕТА: ВЫДУМАННЫЙ_СЕКРЕТ}},
                       ensure_ascii=False).encode("utf-16"))
        сказано = self.отказ(lambda: ap.make_backup([]))
        self.assertIn(self.сломанный.name, сказано, "файл не назван")
        self.assertIn("не провер", сказано.lower(), "причина не названа")
        self.assertFalse(ap.BACKUPS.exists(), "копия всё-таки снята")
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, сказано,
                         "отказ вынес содержимое наружу")


# ==========================================================================
# Свежая проверка ТЕКСТА копии: обход по структуре не читает имена полей
# ==========================================================================
class СекретВИмениПоля(Дом):
    """Имя поля — тоже текст, и в копию оно уезжает так же открыто."""

    def setUp(self):
        super().setUp()
        self.записать({"env": {ИМЯ_ПОЛЯ_С_СЕКРЕТОМ: "1"}})

    def test_копия_не_сохраняется(self):
        self.отказ(lambda: ap.make_backup([]))
        self.assertFalse(ap.BACKUPS.exists(),
                         "копия с незакрытым значением всё-таки сохранена")

    def test_значение_наружу_не_выходит(self):
        сказано = self.отказ(lambda: ap.make_backup([]))
        self.assertNotIn("придуманный7", сказано,
                         "отказ напечатал само значение")
        self.assertIn("settings.json", сказано, "файл не назван")


# ==========================================================================
# (в) обратный контроль: обычный файл с секретом — как и прежде
# ==========================================================================
class ОбычныйФайлССекретом(Дом):
    """Прежнее поведение обязано сохраниться, иначе тесты выше пусты."""

    def setUp(self):
        super().setUp()
        self.записать({"theme": "dark",
                       "env": {ПОЛЕ_СЕКРЕТА: ВЫДУМАННЫЙ_СЕКРЕТ,
                               "ANTHROPIC_MODEL": "opus"}})

    def место(self) -> list:
        return [{"location": f"env.{ПОЛЕ_СЕКРЕТА}", "file": "settings.json",
                 "why": "имя поля указывает на секрет"}]

    def test_значение_вырезано_метка_на_месте(self):
        текст = self.копия(ap.make_backup(self.место()))
        self.assertNotIn(ВЫДУМАННЫЙ_СЕКРЕТ, текст)
        self.assertIn(ap.REDACTION_MARK, текст)

    def test_отпечаток_и_длина_остаются(self):
        текст = self.копия(ap.make_backup(self.место()))
        self.assertIn("fp=", текст, "по копии не узнать, тот ли это секрет")
        self.assertIn("len=", текст)

    def test_соседние_значения_целы(self):
        копия = json.loads(self.копия(ap.make_backup(self.место())))
        self.assertEqual(копия["theme"], "dark")
        self.assertEqual(копия["env"]["ANTHROPIC_MODEL"], "opus")

    def test_формат_копии_не_изменился(self):
        """Пополевой откат держится на этой метке — её трогать нельзя."""
        сведения = ap.make_backup(self.место())
        self.assertEqual(сведения["format"], "superstack.undo.v2")
        self.assertEqual(сведения["before"]["settings.json"],
                         {"before_exists": True})

    def test_файл_без_секретов_копируется_целиком(self):
        """Обратный контроль к отказам: лишней осторожности тоже есть предел."""
        данные = {"theme": "dark", "permissions": {"defaultMode": "plan"},
                  "statusLine": {"type": "command",
                                 "command": "npx -y ccusage statusline"},
                  "env": {"ANTHROPIC_MODEL": "opus", "AWS_REGION": "eu-central-1"}}
        self.записать(данные)
        сведения = ap.make_backup([])
        self.assertEqual(json.loads(self.копия(сведения)), данные)
        self.assertEqual(сведения["redacted"], [])


if __name__ == "__main__":
    unittest.main()
